/*
 * Generator for the Jasmin EC-leaf tables (gen/ec_tables.jinc).
 *
 * The toy curve group (y^2 = x^3 + x + 1 over Fp = Z/23, see ec_ref.h) is cyclic
 * of order 28, generated by G = (0,1): every finite point is some multiple j*G,
 * j in 1..27, and the 28th element is the point at infinity (j = 0).  We exploit
 * that to give the Jasmin leaves a table-driven implementation with NO modular
 * inverse: a point P = j*G is represented internally by its discrete log j, EC
 * point-add is (i + j) mod 28, and EC scalar-mul is (k * j) mod 28.
 *
 * This program emits two tables, computed entirely by the ec_ref.h schoolbook
 * arithmetic (NO hand-typed group data):
 *
 *   POW[j]    : the on-wire bytes (x, y) of j*G, for j = 0..27   (dlog -> point)
 *   DLOG[idx] : the discrete log j of the finite point with idx = 23*x + y,
 *               or 255 for off-curve idx                          (point -> dlog)
 *
 * The Jasmin leaves (ec_leaves.jinc) read these tables, so the compiled leaves
 * compute exactly the ec_ref.h group law.  Regenerate with `make gen/ec_tables.jinc`.
 *
 * On the wire a point is two bytes (x, y) with the point at infinity = (0xff,0xff).
 */
#include <stdio.h>
#include <stdint.h>
#include "ec_ref.h"

#define ORDER 28

int main(void) {
  /* POW[j] = j*G as (x, y) on the wire (infinity encoded (0xff,0xff)). */
  ec_point pow[ORDER];
  ec_point G = { 0, 1 };
  ec_point R = ec_inf();
  pow[0] = R;
  for (int j = 1; j < ORDER; j++) { R = ec_point_add_ref(R, G); pow[j] = R; }

  /* DLOG[23*x + y] = j with j*G = (x,y); 255 if (x,y) is off-curve. */
  uint8_t dlog[23 * 23];
  for (int i = 0; i < 23 * 23; i++) dlog[i] = 255;
  for (int j = 1; j < ORDER; j++) dlog[23 * pow[j].x + pow[j].y] = (uint8_t)j;

  printf("/* GENERATED by gen_tables.c from ec_ref.h -- do not edit by hand.\n");
  printf("   Toy curve y^2 = x^3 + x + 1 over Z/23; cyclic group of order %d,\n", ORDER);
  printf("   generator G = (0,1).  POW: dlog -> (x,y); DLOG: 23*x+y -> dlog. */\n\n");

  printf("param int EC_ORDER = %d;\n\n", ORDER);

  /* POW as a flat u8[2*ORDER] global: POW[2*j], POW[2*j+1] = (x_j, y_j). */
  printf("u8[%d] EC_POW = {\n", 2 * ORDER);
  for (int j = 0; j < ORDER; j++) {
    printf("  0x%02x, 0x%02x%s   // %2d*G\n",
           pow[j].x, pow[j].y, (j == ORDER - 1) ? "" : ",", j);
  }
  printf("};\n\n");

  /* DLOG as a flat u8[529] global. */
  printf("u8[%d] EC_DLOG = {\n", 23 * 23);
  for (int i = 0; i < 23 * 23; i++) {
    printf("0x%02x%s", dlog[i], (i == 23 * 23 - 1) ? "" : ",");
    if ((i % 16) == 15) printf("\n");
  }
  printf("\n};\n");

  return 0;
}
